<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';$u=cal_auth_require('admin');const F=__DIR__.'/storage/auth/api-tokens.json';
function loadt(){if(!is_file(F))return [];$x=json_decode((string)file_get_contents(F),true);return is_array($x)?$x:[];}function savet($x){$d=dirname(F);if(!is_dir($d))mkdir($d,0770,true);file_put_contents(F,json_encode(array_values($x),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);}
$shown='';if($_SERVER['REQUEST_METHOD']==='POST'){$a=(string)($_POST['action']??'');$t=loadt();if($a==='create'){$raw='cal_'.bin2hex(random_bytes(24));$t[]=['id'=>bin2hex(random_bytes(8)),'name'=>trim((string)($_POST['name']??'Integration')),'role'=>in_array($_POST['role']??'viewer',['viewer','editor','admin'],true)?$_POST['role']:'viewer','token_hash'=>hash('sha256',$raw),'active'=>true,'created_at'=>gmdate('c')];savet($t);$shown=$raw;}elseif($a==='revoke'){foreach($t as &$x)if(($x['id']??'')===($_POST['id']??''))$x['active']=false;savet($t);}}
$t=loadt();?><!doctype html><html lang="de"><head><meta charset="utf-8"><title>Calendar API Tokens</title><style>body{font:16px system-ui;max-width:900px;margin:40px auto;padding:0 20px}input,select,button{padding:8px;margin:4px}code{word-break:break-all;background:#eee;padding:8px;display:block}table{border-collapse:collapse;width:100%}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}</style></head><body><p><a href="docs/API.html">← API-Dokumentation</a></p><h1>Calendar API-Tokens</h1><?php if($shown):?><p><strong>Token – nur jetzt vollständig sichtbar:</strong><code><?=htmlspecialchars($shown)?></code></p><?php endif;?><form method="post"><input type="hidden" name="action" value="create"><input name="name" required placeholder="Anwendung"><select name="role"><option>viewer</option><option>editor</option><option>admin</option></select><button>Token erzeugen</button></form><table><tr><th>Name</th><th>Rolle</th><th>Status</th><th></th></tr><?php foreach($t as $x):?><tr><td><?=htmlspecialchars((string)$x['name'])?></td><td><?=htmlspecialchars((string)$x['role'])?></td><td><?=!empty($x['active'])?'aktiv':'widerrufen'?></td><td><?php if(!empty($x['active'])):?><form method="post"><input type="hidden" name="action" value="revoke"><input type="hidden" name="id" value="<?=htmlspecialchars((string)$x['id'])?>"><button>Widerrufen</button></form><?php endif;?></td></tr><?php endforeach;?></table></body></html>
